import re

ROW = re.compile(r'^(?P<pv>\S+)\s+(?P<pvid>[0-9a-fA-F]{16}|none)(?:\s+(?P<vg>\S+)(?:\s+(?P<st>\S+))?)?\s*$')
KEY = re.compile(r'(?:^|(?<=\s\s))((?:[A-Z][A-Za-z]* )*[A-Z][A-Za-z]*:)|(?<=\s)(VG IDENTIFIER)(?= )')

def parse(lines):
    blocks = []
    skip = []
    table = None
    kv = None
    for i, line in enumerate(lines):
        s = line.strip()
        if not s:
            continue
        if s.startswith('#'):
            skip.append(i)
            kv = None
            continue
        m = ROW.match(s)
        if m and ':' not in s:
            if table is None:
                table = {'name': 'physical_volumes', 'kind': 'table', 'lines': [], 'records': []}
                blocks.append(table)
            table['lines'].append(i)
            table['records'].append({'Physical Volume': m.group('pv'), 'PVID': m.group('pvid'), 'Volume Group': m.group('vg') or '', 'State': m.group('st') or ''})
            continue
        ms = list(KEY.finditer(line))
        if ms and ms[0].start() <= len(line) - len(line.lstrip()):
            if kv is None:
                kv = {'name': 'pv_details', 'kind': 'kv', 'lines': [], 'records': [{}]}
                blocks.append(kv)
            rec = kv['records'][0]
            for j, k in enumerate(ms):
                end = ms[j + 1].start() if j + 1 < len(ms) else len(line)
                key = (k.group(1) or k.group(2)).rstrip(':').strip()
                rec[key] = line[k.end():end].strip()
            kv['lines'].append(i)
    return {'blocks': blocks, 'skip': skip}
